def copy(src,dest):
 dest=archive/dest;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dest)
 entries.append({'original_path':str(src),'archive_path':str(dest.relative_to(BASE)),'sha256':hashlib.sha256(dest.read_bytes()).hexdigest(),'bytes':dest.stat().st_size})
