findings=[]
for name in ['native_review.json','root_review.json','signals_review.json','legacy_review.json']:
 for f in json.loads((SRC/'reviews'/name).read_text())['findings']:
  fid=f['id'];findings.append(fid)
  cat='current_verified_repair' if fid in repair else 'integration_proof' if fid in proof else 'no_change' if fid in nochange else 'historical_comparison' if fid.startswith('LEG-') or fid in compare else 'document_correction'
